def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def best_by(items, keyfunc, default=None):
        best_item = default
        best_score = None
        for it in items or []:
            try:
                s = keyfunc(it)
            except Exception:
                continue
            if best_score is None or s < best_score:
                best_score = s
                best_item = it
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_p = (sx, sy)
    opp_p = (ox, oy)
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0
    center = (w // 2, h // 2) if w and h else self_p

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_p, opp_p)
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = best_by(corners, lambda c: -manhattan(c, opp_p), default=center)
        return step_toward(self_p, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        if targets:
            # Prefer cells closer to us but farther from opponent.
            target = best_by(
                targets,
                lambda t: manhattan(pos(t), self_p) * 2 - manhattan(pos(t), opp_p),
                default=None,
            )
            if target is not None:
                return step_toward(self_p, pos(target))
        # If no clear target, drift toward center or pressure opponent.
        return step_toward(self_p, center if center != self_p else opp_p)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        # Prefer resources that are close to us and not too close to opponent.
        target = best_by(
            resources,
            lambda r: manhattan(pos(r), self_p) * 2 + max(0, 4 - manhattan(pos(r), opp_p)),
            default=None,
        )
        if target is not None:
            return step_toward(self_p, pos(target))

    # Fallbacks: if no resources, either chase or evade depending on apparent role.
    if observation.get("self_role") == "evader":
        return step_away(self_p, opp_p)
    return step_toward(self_p, opp_p if env == "pursuit_evasion" else center)

